any.script:
var phase = PhaseManager.get_current_phase_instance()
if phase == null or not phase.has_method("get_active_move_data"):
	return false
var am = phase.get("active_moves")
if typeof(am) != TYPE_DICTIONARY:
	return false
for uid in am:
	var dists = am[uid].get("model_distances", {})
	for k in dists:
		if float(dists[k]) >= 0.1:
			return true
return false
